"""
Value iteration for Bellman deep hedging.

Initialises V^0 = 0 (critic with zero bias) and iterates V^{n+1} = TV^n by
alternating:
  * Actor step  : optimise policy pi^n given V^{n-1}.
  * Critic step : fit V^n to the Bellman targets TV^{n-1} generated by pi^n.
"""
import torch
import torch.nn as nn
import math
import numpy as np
from typing import List, Optional


class ValueIterator:
    """Runs Bellman value iteration for deep hedging.

    Args:
        actor: BellmanActor whose parameters are updated in the actor step.
        critic: BellmanCritic whose parameters are updated in the critic step.
        beta: Discount factor in (0, 1).
        risk_aversion: Exponential utility coefficient a > 0.
        cost_epsilon: Proportional transaction-cost rate.
    """

    def __init__(self, actor: nn.Module, critic: nn.Module,
                 beta: float = 0.99, risk_aversion: float = 1.0,
                 cost_epsilon: float = 0.0):
        self.actor = actor
        self.critic = critic
        self.beta = beta
        self.a = risk_aversion
        self.cost_epsilon = cost_epsilon
        self.v_values: List[float] = []  # ||V^n|| convergence tracking

    def utility(self, x: torch.Tensor) -> torch.Tensor:
        """Exponential utility u(x) = (1 - exp(-a*x)) / a."""
        return (1.0 - torch.exp(-self.a * x)) / self.a

    def actor_step(self, states: torch.Tensor, dZ: torch.Tensor,
                   dH: torch.Tensor, next_states: torch.Tensor,
                   n_actor_epochs: int = 50, lr: float = 1e-3) -> List[float]:
        """Optimise actor given the current critic (V^{n-1}).

        Args:
            states: Current state batch [N, state_dim].
            dZ: Portfolio P&L from liability alone [N].
            dH: Hedge instrument gains [N, n_instruments].
            next_states: Next-period state batch [N, state_dim].
            n_actor_epochs: Number of gradient steps.
            lr: Adam learning rate.

        Returns:
            List of per-epoch actor losses.
        """
        optimizer = torch.optim.Adam(self.actor.parameters(), lr=lr)
        losses = []

        for _ in range(n_actor_epochs):
            optimizer.zero_grad()
            actions = self.actor(states)  # [N, n_instruments]

            cost = self.cost_epsilon * actions.abs().sum(dim=-1)
            gain = (actions * dH).sum(dim=-1) + dZ - cost

            with torch.no_grad():
                V_next = self.critic(next_states)

            target = self.beta * V_next + gain
            # Numerically stable entropic risk measure via log-sum-exp
            N = target.shape[0]
            lse = torch.logsumexp(-self.a * target, dim=0) - math.log(N)
            loss = lse / self.a  # minimise = maximise -(1/a)*log(E[exp(-a*X)])
            loss.backward()
            torch.nn.utils.clip_grad_norm_(self.actor.parameters(), max_norm=1.0)
            optimizer.step()
            losses.append(loss.item())

        return losses

    def critic_step(self, states: torch.Tensor, dZ: torch.Tensor,
                    dH: torch.Tensor, next_states: torch.Tensor,
                    n_critic_epochs: int = 50, lr: float = 1e-3) -> List[float]:
        """Fit the critic V^n to Bellman targets generated by the current actor.

        Args:
            states: Current state batch [N, state_dim].
            dZ: Portfolio P&L from liability alone [N].
            dH: Hedge instrument gains [N, n_instruments].
            next_states: Next-period state batch [N, state_dim].
            n_critic_epochs: Number of gradient steps.
            lr: Adam learning rate.

        Returns:
            List of per-epoch MSE losses.
        """
        with torch.no_grad():
            actions = self.actor(states)
            cost = self.cost_epsilon * actions.abs().sum(dim=-1)
            gain = (actions * dH).sum(dim=-1) + dZ - cost
            V_next = self.critic(next_states)
            targets = self.beta * V_next + gain  # [N]

        optimizer = torch.optim.Adam(self.critic.parameters(), lr=lr)
        losses = []

        for _ in range(n_critic_epochs):
            optimizer.zero_grad()
            V_pred = self.critic(states)
            loss = nn.MSELoss()(V_pred, targets)
            loss.backward()
            optimizer.step()
            losses.append(loss.item())

        self.v_values.append(targets.abs().mean().item())
        return losses

    def run(self, states: torch.Tensor, dZ: torch.Tensor,
            dH: torch.Tensor, next_states: torch.Tensor,
            n_iterations: int = 5,
            n_actor_epochs: int = 50,
            n_critic_epochs: int = 50) -> List[dict]:
        """Run full value iteration for n_iterations actor-critic cycles.

        Args:
            states: Current state batch [N, state_dim].
            dZ: Portfolio P&L from liability [N].
            dH: Hedge instrument gains [N, n_instruments].
            next_states: Next-period state batch [N, state_dim].
            n_iterations: Number of (actor_step, critic_step) cycles.
            n_actor_epochs: Gradient steps per actor step.
            n_critic_epochs: Gradient steps per critic step.

        Returns:
            List of per-iteration diagnostics dicts with keys
            'iteration', 'actor_loss', 'critic_loss', 'v_norm'.
        """
        history = []
        for n in range(n_iterations):
            actor_losses = self.actor_step(
                states, dZ, dH, next_states, n_actor_epochs
            )
            critic_losses = self.critic_step(
                states, dZ, dH, next_states, n_critic_epochs
            )
            entry = {
                "iteration": n,
                "actor_loss": actor_losses[-1],
                "critic_loss": critic_losses[-1],
                "v_norm": self.v_values[-1],
            }
            history.append(entry)
            print(
                f"Iteration {n + 1}/{n_iterations}: "
                f"Actor loss={actor_losses[-1]:.4f}, "
                f"Critic loss={critic_losses[-1]:.6f}, "
                f"V_norm={self.v_values[-1]:.4f}"
            )
        return history
